<?php

namespace App\Http\Controllers;

use Illuminate\Support\Facades\File;
use Inertia\Inertia;
use Inertia\Response;

/**
 * Public Glenride standards page (dvaughnhouse.org/standards).
 * Source of truth is the markdown in resources/standards/*.md; the .html
 * files beside them are generated by resources/standards/build.sh.
 */
class StandardsController extends Controller
{
    /**
     * Display the "How Glenride Works" standards page.
     */
    public function show(): Response
    {
        $path = resource_path('standards/how-glenride-works.html');

        if (! File::exists($path)) {
            abort(404, 'Standards page not found.');
        }

        return Inertia::render('Standards/Show', [
            'document' => [
                'title' => 'How Glenride Works',
                'html' => File::get($path),
            ],
        ]);
    }
}
